-- Per-game screenshot gallery. The files live under DATA_DIR/screenshots/<game_id>/ (the original untouched plus a
-- small JPEG thumbnail); only their metadata is here. File names are random hex generated by the server.
CREATE TABLE screenshot (
    id       INTEGER PRIMARY KEY,
    game_id  INTEGER NOT NULL REFERENCES game(id) ON DELETE CASCADE,
    file     TEXT NOT NULL,               -- original, e.g. 3f9c...e1.png
    thumb    TEXT NOT NULL,               -- thumbnail, e.g. 3f9c...e1_t.jpg
    width    INTEGER NOT NULL,
    height   INTEGER NOT NULL,
    bytes    INTEGER NOT NULL,
    taken_at TEXT,                        -- EXIF DateTimeOriginal, else the file's last-modified time, else NULL
    caption  TEXT,
    pos      INTEGER NOT NULL,
    added_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now'))
) STRICT;
CREATE INDEX idx_screenshot_game ON screenshot(game_id, pos);
